-- Synthetic fixtures only. No external messages, notifications or real reports. Entire suite rolls back.
begin;
create temp table sg_test(key text primary key,value text);
grant select,insert,update on sg_test to authenticated;
do $$declare g uuid:=gen_random_uuid();p uuid:=gen_random_uuid();o uuid:=gen_random_uuid();s uuid:=gen_random_uuid();r uuid:=gen_random_uuid();u uuid:=gen_random_uuid();c uuid;d uuid;
begin
 insert into auth.users(id,email,aud,role,email_confirmed_at,created_at,updated_at) select id,'sg-synthetic-'||id||'@example.invalid','authenticated','authenticated',now(),now(),now() from unnest(array[g,p,o,s,r,u]) id;
 update auth.users set email_confirmed_at=null where id=u;
 insert into public.guardian_profiles(user_id,display_name) values(g,'Synthetic family');
 insert into public.staff_members(user_id,role,active) values(s,'coach',true),(r,'manager',false),(u,'coach',true);
 insert into public.coaching_players(first_name,last_name,programme,consent_confirmed,consent_recorded_by,created_by) values('Safeguarding','Synthetic','Assessment',true,s,s) returning id into c;
 insert into public.coaching_players(first_name,last_name,programme,consent_confirmed,consent_recorded_by,created_by) values('Other','Synthetic','Assessment',true,s,s) returning id into d;
 insert into public.guardian_player_links(guardian_id,player_id,approved_by) values(g,c,s);
 insert into public.player_account_links(user_id,player_id,approved_by) values(p,c,g);
 insert into sg_test values('guardian',g::text),('player',p::text),('other',o::text),('staff',s::text),('revoked',r::text),('unverified',u::text),('core',c::text),('other_core',d::text),('request',gen_random_uuid()::text);
 if has_function_privilege('anon','public.star_safeguarding(text,jsonb)','execute') then raise exception 'Anonymous RPC exposed';end if;
 if has_table_privilege('authenticated','star_private.safeguarding_cases','select') or has_table_privilege('authenticated','star_private.safeguarding_events','insert') or has_table_privilege('authenticated','star_private.safeguarding_audit','delete') then raise exception 'Raw records exposed';end if;
 if (select count(*) from pg_class cl join pg_namespace n on n.oid=cl.relnamespace where n.nspname='star_private' and cl.relname like 'safeguarding_%' and cl.relkind='r' and not cl.relrowsecurity)>0 then raise exception 'Missing RLS';end if;
end $$;
set local role authenticated;
select set_config('request.jwt.claim.sub',(select value from sg_test where key='player'),true);
do $$declare data jsonb:=jsonb_build_object('player_id',(select value from sg_test where key='core'),'body','Synthetic original words','parent_requested',false,'request_id',(select value from sg_test where key='request'));a jsonb;b jsonb;begin
 a:=public.star_safeguarding('submit',data);b:=public.star_safeguarding('submit',data);
 if a<>b or a->>'reference' is null then raise exception 'Receipt/idempotency failed';end if;
 insert into sg_test values('case',a->>'id');
 begin perform public.star_safeguarding('submit',data||'{"body":"changed"}');raise exception 'Changed retry accepted';exception when raise_exception then if sqlerrm='Changed retry accepted' then raise;end if;end;
 begin perform public.star_safeguarding('submit',data||jsonb_build_object('player_id',(select value from sg_test where key='other_core'),'request_id',gen_random_uuid()));raise exception 'Cross player submission accepted';exception when insufficient_privilege then null;end;
 if jsonb_array_length(public.star_safeguarding('player_list',jsonb_build_object('player_id',(select value from sg_test where key='core'))))<>1 then raise exception 'Player list incorrect';end if;
 begin perform public.star_safeguarding('summary');raise exception 'Player saw staff alerts';exception when insufficient_privilege then null;end;
end $$;
select set_config('request.jwt.claim.sub',(select value from sg_test where key='guardian'),true);
do $$declare id text:=(select value from sg_test where key='case');begin
 begin perform public.star_safeguarding('player_read',jsonb_build_object('id',id));raise exception 'Guardian read report';exception when insufficient_privilege then null;end;
 begin perform public.star_safeguarding('summary');raise exception 'Guardian saw counts';exception when insufficient_privilege then null;end;
 begin perform public.star_safeguarding('intake','{"subject":"x","body":"x","request_id":"00000000-0000-0000-0000-000000000001"}');raise exception 'Guardian used staff intake';exception when insufficient_privilege then null;end;
end $$;
select set_config('request.jwt.claim.sub',(select value from sg_test where key='other'),true);
do $$begin
 begin perform public.star_safeguarding('player_read',jsonb_build_object('id',(select value from sg_test where key='case')));raise exception 'Other account read case';exception when insufficient_privilege then null;end;
 begin perform public.star_safeguarding('resources');raise exception 'Nonstaff read resources';exception when insufficient_privilege then null;end;
end $$;
select set_config('request.jwt.claim.sub',(select value from sg_test where key='revoked'),true);
do $$begin begin perform public.star_safeguarding('list');raise exception 'Inactive staff read register';exception when insufficient_privilege then null;end;end$$;
select set_config('request.jwt.claim.sub',(select value from sg_test where key='unverified'),true);
do $$begin begin perform public.star_safeguarding('list');raise exception 'Unverified staff read register';exception when insufficient_privilege then null;end;end$$;
select set_config('request.jwt.claim.sub',(select value from sg_test where key='staff'),true);
do $$declare id text:=(select value from sg_test where key='case');a jsonb;data jsonb;tid text;begin
 if public.star_safeguarding('summary')->>'unread'='0' then raise exception 'Missing persisted alert';end if;
 a:=public.star_safeguarding('read',jsonb_build_object('id',id));
 if a->'case'->>'original_body'<>'Synthetic original words' then raise exception 'Staff read failed';end if;
 data:=jsonb_build_object('id',id,'kind','judgement','body','Internal synthetic judgement','request_id',gen_random_uuid());
 perform public.star_safeguarding('event',data);perform public.star_safeguarding('event',data);
 perform public.star_safeguarding('event',jsonb_build_object('id',id,'kind','staff_reply','body','Synthetic private reply','request_id',gen_random_uuid()));
 a:=public.star_safeguarding('read',jsonb_build_object('id',id));
 if jsonb_array_length(a->'events')<>3 then raise exception 'Event retry duplicated';end if;
 data:=jsonb_build_object('id',id,'revision',(a->'case'->>'revision')::integer,'status','open','priority','urgent','assigned_to',(select value from sg_test where key='staff'),'body','Synthetic decision rationale','legal_hold',true,'request_id',gen_random_uuid());
 perform public.star_safeguarding('update',data);perform public.star_safeguarding('update',data);
 begin perform public.star_safeguarding('update',data||jsonb_build_object('request_id',gen_random_uuid()));raise exception 'Stale update accepted';exception when raise_exception then if sqlerrm='Stale update accepted' then raise;end if;end;
 perform public.star_safeguarding('task_add',jsonb_build_object('id',id,'title','Synthetic action','body','Synthetic task reason','assigned_to',(select value from sg_test where key='staff'),'due_at',now()-interval '1 hour','request_id',gen_random_uuid()));
 a:=public.star_safeguarding('read',jsonb_build_object('id',id));tid:=a->'tasks'->0->>'id';
 if tid is null then raise exception 'Action missing';end if;
 if (public.star_safeguarding('summary')->>'overdue')::integer<1 then raise exception 'Overdue action missing';end if;
 perform public.star_safeguarding('task_complete',jsonb_build_object('id',id,'task_id',tid,'body','Synthetic completion outcome','request_id',gen_random_uuid()));
 perform public.star_safeguarding('event',jsonb_build_object('id',id,'kind','parent_contact','body','No parent contact: synthetic safety decision','request_id',gen_random_uuid()));
 perform public.star_safeguarding('event',jsonb_build_object('id',id,'kind','referral','body','Synthetic agency record only; nothing sent','request_id',gen_random_uuid()));
 a:=public.star_safeguarding('export',jsonb_build_object('id',id));
 if not exists(select 1 from jsonb_array_elements(a->'audit') x where x->>'action'='export') then raise exception 'Export not audited';end if;
 begin update star_private.safeguarding_events set body='overwrite';raise exception 'Chronology mutable';exception when insufficient_privilege then null;end;
 perform public.star_safeguarding('resource_add',jsonb_build_object('title','Synthetic procedure','version','test','body','Synthetic only','request_id',gen_random_uuid()));
 a:=public.star_safeguarding('resources');perform public.star_safeguarding('resource_ack',jsonb_build_object('id',a->'resources'->0->>'id'));
end $$;
select set_config('request.jwt.claim.sub',(select value from sg_test where key='player'),true);
do $$declare id text:=(select value from sg_test where key='case');a jsonb;data jsonb;begin
 a:=public.star_safeguarding('player_read',jsonb_build_object('id',id));
 if a ? 'audit' or a ? 'case' or a ? 'tasks' or a::text like '%Internal synthetic judgement%' or a::text like '%Synthetic decision rationale%' or a::text like '%Synthetic agency%' or a::text like '%@example.invalid%' then raise exception 'Internal record leaked to player';end if;
 if jsonb_array_length(a->'events')<>1 or a->'events'->0->>'body'<>'Synthetic private reply' then raise exception 'Private reply projection incorrect';end if;
 data:=jsonb_build_object('id',id,'body','Synthetic followup','request_id',gen_random_uuid());perform public.star_safeguarding('player_reply',data);perform public.star_safeguarding('player_reply',data);
 if jsonb_array_length(public.star_safeguarding('player_read',jsonb_build_object('id',id))->'events')<>2 then raise exception 'Reply retry incorrect';end if;
 begin perform public.star_safeguarding('event',data||'{"kind":"decision"}');raise exception 'Player wrote internal note';exception when insufficient_privilege then null;end;
end $$;
reset role;
-- Retained records survive loss of family/player access; no account deletion cascade.
delete from public.guardian_player_links where player_id=(select value::uuid from sg_test where key='core');
set local role authenticated;
select set_config('request.jwt.claim.sub',(select value from sg_test where key='player'),true);
do $$begin begin perform public.star_safeguarding('player_read',jsonb_build_object('id',(select value from sg_test where key='case')));raise exception 'Revoked player kept access';exception when insufficient_privilege then null;end;end $$;
reset role;
update public.staff_members set active=false where user_id=(select value::uuid from sg_test where key='staff');
set local role authenticated;
select set_config('request.jwt.claim.sub',(select value from sg_test where key='staff'),true);
do $$begin begin perform public.star_safeguarding('read',jsonb_build_object('id',(select value from sg_test where key='case')));raise exception 'Revoked staff kept case access';exception when insufficient_privilege then null;end;end$$;
select set_config('request.jwt.claims',jsonb_build_object('sub',(select value from sg_test where key='player'),'session_id',gen_random_uuid())::text,true);
do $$begin begin perform public.star_safeguarding('player_list',jsonb_build_object('player_id',(select value from sg_test where key='core')));raise exception 'Invalid session accepted';exception when insufficient_privilege then null;end;end$$;
select set_config('request.jwt.claims','{}',true);
select set_config('request.jwt.claim.sub','',true);
do $$begin begin perform public.star_safeguarding('summary');raise exception 'Missing identity accepted';exception when insufficient_privilege then null;end;end$$;
reset role;
rollback;
select 'Safeguarding permission, confidentiality, retry, chronology, actions, audit and revocation checks passed; all synthetic fixtures rolled back.' as result;
